/*
 * A266666  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 51" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A266666
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   let r = floor(sqrt(n)) c = n - r^2 // column index within row r
 *            (0 … 2r) The triangular row r has length 2r+1. Value at column c
 *            is 1 if (r is even and c == r) // only the centre cell when r is
 *            even or (r is odd and c != r) // all cells except the centre
 *            when r is odd otherwise the value is 0
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

/* Integer square root for 64‑bit unsigned integers.  */
static inline uint64_t _isqrt_u64(uint64_t v)
{
    uint64_t lo = 0, hi = 0xFFFFFFFFULL;      /* hi^2 <= 2^64-1 */
    while (lo <= hi) {
        uint64_t mid = (lo + hi) >> 1;
        __uint128_t sq = (__uint128_t)mid * mid;
        if (sq == v)
            return mid;
        if (sq < v) {
            if (mid == 0xFFFFFFFFULL) break;  /* avoid overflow on next increment */
            lo = mid + 1;
        } else {
            if (mid == 0) break;
            hi = mid - 1;
        }
    }
    return hi;
}

seq_t a(idx_t n)
{
    /* compute the row index r */
    uint64_t r = _isqrt_u64(n);
    /* check that r^2 <= n < (r+1)^2; r computed by floor(sqrt(n)) guarantees this */
    uint64_t r2 = r * r;
    uint64_t c = n - r2;            /* column within row r, 0 ≤ c ≤ 2r */
    uint64_t pos = c - r;           /* position relative to the centre, -r … +r */

    uint64_t value;
    if ((r & 1ULL) == 0ULL) {       /* r even: centre is 1 */
        value = (pos == 0ULL) ? 1ULL : 0ULL;
    } else {                        /* r odd: all except centre are 1 */
        value = (pos == 0ULL) ? 0ULL : 1ULL;
    }
    return (seq_t)value;
}
